    76|const TRANSIENT_STATUS_CODES = new Set([429, 502, 503, 504, 408]);
    77|const PERMANENT_STATUS_CODES = new Set([400, 401, 403, 404, 422]);
    78|const TRANSIENT_MESSAGE_PATTERN = /timed?\s?out|timeout|connection reset|econnreset|econnrefused|socket hang ?up|network request failed|fetch failed|temporarily unavailable|service unavailable|rate.?limit|too many requests|aborted|etimedout|eai_again|overloaded/i;
