    81|/** Retry ONLY transient failures: 429/502/503/504, resets, timeouts (owner rule). */
    82|export function classifyFailureForRetry(input: { httpStatus?: number | null; message: string }): FailureClassification {
    83|  const status = input.httpStatus ?? null;
    84|  if (status !== null && PERMANENT_STATUS_CODES.has(status)) {
    85|    return { transient: false, code: `HTTP_${status}_PERMANENT` };
    86|  }
    87|  if (PERMANENT_MESSAGE_PATTERN.test(input.message)) {
    88|    return { transient: false, code: 'PERMANENT_INPUT_OR_AUTH' };
    89|  }
    90|  if (status !== null && TRANSIENT_STATUS_CODES.has(status)) {
    91|    return { transient: true, code: `HTTP_${status}_TRANSIENT` };
    92|  }
    93|  if (status !== null && status >= 500) {
    94|    return { transient: true, code: `HTTP_${status}_TRANSIENT` };
    95|  }
    96|  if (TRANSIENT_MESSAGE_PATTERN.test(input.message)) {
