   119|
   120|/** Decide next status after a failed attempt. Exhausted transient retries → dead letter. */
   121|export function nextStatusAfterFailure(retryCount: number, maxRetries: number, transient: boolean): FailureOutcome {
   122|  if (!transient) return { status: 'FAILED', deadLetter: false };
   123|  if (retryCount >= maxRetries) return { status: 'FAILED', deadLetter: true };
   124|  return { status: 'RETRYING', deadLetter: false };
